 B={}
 for s,row in enumerate(C):
  if sum(ns[i] for i in range(t) if s>>i&1)<=7:continue
  while row:
   p=row.bit_length()-1
   if p in B:row^=B[p]
   else:B[p]=row;break
 basis=[]
 for i in range(len(cells)):
  if i in B:continue
